def match_parens(lst):
    if len(lst) != 2:
        return 'No'

    for string in lst:
        if not all(char in ['(', ')'] for char in string):
            return 'No'

    count_open = sum(1 for char in ''.join(lst) if char == '(')
    count_close = sum(1 for char in ''.join(lst) if char == ')')

    if count_open != count_close:
        return 'No'

    def is_balanced(s):
        stack = []
        for char in s:
            if char == '(':
                stack.append(char)
            elif char == ')':
                if not stack:
                    return False
                stack.pop()
        return not stack

    for i in range(2):
        for j in range(2):
            if is_balanced(lst[i] + lst[j]):
                return 'Yes'

    return 'No'

