def match_parens(lst):
    if not any(lst):
        return 'Yes'

    open_count = 0
    close_count = 0

    for s in lst:
        open_count += s.count('(')
        close_count += s.count(')')

    if open_count != close_count:
        return 'No'

    concatenated = ''.join(lst)

    stack = []
    for char in concatenated:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return 'No'
            stack.pop()

    if not stack:
        return 'Yes'
    else:
        return 'No'

