    def calculate_power_of_2(n):
        result = 1
        base = 2
        while n > 0:
            if n % 2 == 1:
                result = (result * base) % p
            base = (base * base) % p
            n //= 2
        return result

    def calculate_modulo(num, p):
        return num % p

    return calculate_modulo(calculate_power_of_2(n), p)

