    str1, str2 = lst[0], lst[1]
    if '(' not in str1 and ')' not in str1 and '(' not in str2 and ')' not in str2:
        return 'No'

    all_combinations = [str1 + str2, str2 + str1]

    for combination in all_combinations:
        if is_balanced(combination):
            return 'Yes'

    return 'No'

