def match_parens(lst):
    if len(lst) != 2:
        return 'No'

    for s in lst:
        if set(s) != {'(', ')'}:
            return 'No'

    def is_balanced(s):
        stack = []
        for char in s:
            if char == '(':
                stack.append(char)
            elif char == ')':
                if not stack:
                    return False
                stack.pop()
        return len(stack) == 0

    s1, s2 = lst[0], lst[1]
    for order in [(s1, s2), (s2, s1)]:
        if is_balanced(order[0] + order[1]):
            return 'Yes'

    return 'No'

