import math

def triangle_area(a, b, c):
    # Validate the input sides to ensure they are positive numbers
    if a <= 0 or b <= 0 or c <= 0:
        return -1

    # Check if the sum of any two sides is greater than the remaining side to determine if it forms a valid triangle
    if a + b <= c or a + c <= b or b + c <= a:
        return -1

    # If it is a valid triangle, calculate the area using Heron's formula
    s = (a + b + c) / 2
    area = math.sqrt(s * (s - a) * (s - b) * (s - c))

    # Round the calculated area to two decimal places
    rounded_area = round(area, 2)

    # Return the rounded area if it is a valid triangle, otherwise return -1
    return rounded_area
