    # Calculate the semi-perimeter by adding all sides and dividing by 2
    s = (a + b + c) / 2

    # Calculate the area using Heron's formula
    area = math.sqrt(s * (s - a) * (s - b) * (s - c))

    # Round the area to 2 decimal points
    area = round(area, 2)

    # Return the area if it's a valid triangle, otherwise return -1
    return area
