def triples_sum_to_zero(l: list):
    def generate_combinations(lst, r):
        if r == 0:
            return [[]]
        if r == 1:
            return [[x] for x in lst]
        combinations = []
        for i in range(len(lst)):
            sub_combinations = generate_combinations(lst[i + 1:], r - 1)
            for sub_combination in sub_combinations:
                combinations.append([lst[i]] + sub_combination)
        return combinations

    def check_sum_zero(combination):
        return sum(combination) == 0

    if len(l) < 3:
        return False

    combinations = generate_combinations(l, 3)
    for combination in combinations:
        if check_sum_zero(combination):
            return True
    return False

